    answer: 'Je Raum stehen die Prüfobjekte auf „in Ordnung“; nur Mängel antippen, Fehlerart wählen, bei Bedarf Notiz und Foto. „Raum fertig, weiter“ geht zum nächsten Raum. Zum Schluss Bemerkung und auf Wunsch die Unterschrift des Kunden, dann „Messung abschließen“. Eine Messung lässt sich unterbrechen und fortsetzen.',
    steps: ['„Messung starten“, Objekt wählen, „Messung beginnen“.', 'Je Raum Mängel antippen und Fehlerart wählen, „Foto“ für ein Bild.', '„Raum fertig, weiter“ bis zum letzten Raum.', 'Unterschreiben lassen (optional) und „Messung abschließen“.'],
    tips: ['Ohne Netz warten die Fotos im Handy und werden später hochgeladen.', '„entfällt“ für Prüfobjekte, die es im Raum nicht gibt.'],
