    answer: 'Ein Raum ist nicht in Ordnung, sobald ein Prüfobjekt einen Mangel hat (Grenze änderbar). Erfüllt ist die Messung, wenn höchstens so viele Räume nicht in Ordnung sind wie zulässig. Die Kennzahl ist der Anteil der Prüfobjekte ohne Mangel, gewichtet, z. B. Sanitärobjekte dreifach. Das Diagramm zeigt sie je Monat mit dem Zielwert.',
