    answer: 'Ein Liegeplatz ist die Stelle beim Kunden, an der Matten liegen, z. B. „Haupteingang“ oder „Stiege 2“. Die Liste zeigt je Kunde und Objekt: Liegeplatz, Matte, Stückzahl, Intervall und nächsten Wechsel. Das bisherige Werkzeug läuft daneben unverändert weiter.',
