    tips: ['Ein zweiter Lauf ändert nichts; er trägt nur nach, was neu ist (jüngere Touren, inzwischen angelegte Mattentypen, neue Liegeplätze).', 'Die Dateien des Werkzeugs werden nie geändert; alte Touren und Lieferscheine werden nicht verrechnet.', 'Übernommene Liegeplätze nicht löschen, sondern auf inaktiv setzen.'],
