    tips: ['Die App erkennt deine Tour über die E-Mail deines Kontos; fehlt sie in den Stammdaten, sieht der Fahrer die Tour nicht.', 'Vergangene, noch offene Touren stehen oben mit Hinweis.', 'Das Büro sieht hier alle Touren mit Fortschritt.'],
    roles: 'Fahrer Mattenwechsel, Mattenwechsel Büro, Vollzugriff',
