    answer: 'Ein Stopp zeigt Kunde, Objekt, Adresse, Zugang und Hinweis und je Liegeplatz die Soll-Matten, z. B. „Haupteingang: 2 × 85 × 150 cm“. „Gewechselt“ übernimmt das Soll; mit Plus und Minus stimmt die Menge, eine Abweichung wird markiert. „Nicht möglich“ braucht einen Grund. Bemerkung und Fotos gehören zum Liegeplatz.',
