    tips: ['Gespeichert werden Zeitpunkt, Fahrer, Ist-Mengen, Abweichungen und Bemerkungen; den Lieferschein erstellt danach das Büro in „Matten-Lieferscheine“.', 'Korrigieren kann nur das Büro: „Korrigieren (Büro)“ öffnet den Stopp wieder, der bisherige Abschluss bleibt nachvollziehbar.'],
