    answer: 'Der Matten-Kalender zeigt die gespeicherten Einsätze je Tag, nach Gebiet und Objekt: Liegeplätze, Matten je Größe, Status in Farbe und unten je Tag die Ladeliste. Oben stehen überfällige und nachzuholende Einsätze. Umschalten zwischen Woche und Monat; am Handy ist es eine Tagesliste.',
