    answer: 'Lieferscheine haben eigene Nummern (LS), auf Wunsch ohne Preise und mit Feld für die Unterschrift des Kunden. Sie sind kein Umsatz. Mehrere Lieferscheine eines Kunden werden mit „Sammelrechnung“ zu einer Rechnung; danach stehen sie auf „verrechnet“.',
