    q: ['proforma', 'proformarechnung', 'pro forma rechnung', 'vorauskasse', 'rechnung vorab', 'proforma umwandeln'],
    answer: 'Eine Proformarechnung (Nummern PF) zeigt dem Kunden vorab, was verrechnet wird, ist aber keine Rechnung im Sinne des UStG: kein Umsatz, kein offener Posten, keine Mahnung, kein Vorsteuerabzug. Nach der Leistung wird sie mit „→ Rechnung“ zur echten Rechnung.',
