    steps: ['Beim Dauerauftrag die Wertsicherung mit Basis-Indexzahl einstellen.', 'Unter „Belege ▾“ → „Daueraufträge“ bei „Indexzahlen“ jeden Monat die neue Zahl „Eintragen“.', 'Beim Monatslauf passt die App die Preise an.'],
