    tips: ['VPI und KV-Lohn werden innerhalb von 12 Monaten nie beide angewandt; nach der KV-Anpassung ist die Indexzahl davor die neue Basis.', 'Ist ein Monat ab „gültig ab“ schon abgerechnet, gilt der neue Preis ab dem nächsten.'],
