    answer: '„Aus Leistungsnachweis“ erstellt je Objekt einen Entwurf für den Monat: regelmäßige Einsätze als Stunden × Stundensatz, Sonderleistungen einzeln mit Datum. Objekte mit Dauerauftrag bekommen nur ihre Sonderleistungen. Grundlage ist der Plan; wahlweise die Ist-Zeiten aus der Zeiterfassung.',
