    answer: 'Im Dialog „Aus Leistungsnachweis“ wählst du die Grundlage: Plan (Standard) oder Ist-Zeiten aus der Zeiterfassung. Ist zählt die gestempelten Zeiten je Objekt, je Stempelung gerundet (ohne, 5 oder 15 Minuten, ab der Hälfte aufwärts). Stempelungen ohne „Gehen“ stehen als Problem da und zählen nicht; die Planzeit dafür nur, wenn du sie ausdrücklich wählst.',
    steps: ['„Anlegen ▾“ → „Aus Leistungsnachweis“ wählen.', 'Bei „Grundlage“ „Ist-Zeiten (Zeiterfassung)“ wählen.', 'Rundung prüfen und die Liste „Nicht gezählt“ ansehen.', 'Objekte anhaken und „Entwürfe erstellen“ klicken.'],
    tips: ['Beim Versand hängt die Einsatzliste an (Datum, von–bis, Dauer, Leistung), auch wenn die Buchhaltung sendet. Namen stehen nur darin, wenn der Leistungsnachweis beim Abrechnen Namen zeigt.', 'Winterdienst zählt hier nicht, dafür gibt es „Winterdienst abrechnen“.'],
