    answer: '„Winterdienst abrechnen“ erstellt je Objekt einen Rechnungsentwurf für den Monat aus dem Winterdienst-Protokoll. Jeder Eintrag zählt als Einsatz: Räumen, Streuen oder Räumen und Streuen, je mit eigenem Preis. Oder eine Pauschale je Monat bzw. Saison, die Einsätze stehen dann als Text dabei. Schon abgerechnete Monate meldet die App.',
