    tips: ['Die Preise merkt sich die App beim Kunden je Objekt (Kundenblatt → „Winterdienst“). Ohne eigene Preise gelten Artikel wie „Winterdienst Räumen und Streuen“ oder „Winterdienst Pauschale“.', 'Reine Kontrollgänge („nichts nötig“) stehen nur mit eigenem Preis auf der Rechnung.', 'Die Saisonpauschale steht einmal je Saison auf der Rechnung, mit Leistungszeitraum der ganzen Saison.', 'Den Nachweis gibt es auch als Knopf „Winterdienst-Nachweis“ neben dem PDF, auch für die Buchhaltung. Namen stehen nur darin, wenn der Leistungsnachweis beim Abrechnen Namen zeigt.'],
