    tips: ['„85x150“ schreibt die App als „85 × 150 cm“. Denselben Typ (Größe, Farbe, Art) gibt es nur einmal.', 'Ein Mattentyp mit Kundenpreisen lässt sich nicht löschen; nicht mehr verwendete inaktiv setzen.', 'Darunter stehen die Kundenpreise für Matten, die heute gelten.'],
