    answer: 'Im Kundenblatt unter „Kundenpreise“ trägst du je Artikel einen eigenen Preis netto mit „gültig ab“ und „gültig bis“ ein (je einschließlich, bis leer = ohne Ende). Er geht dem Preis des Artikels vor; der Kundenrabatt wird dazu nicht noch abgezogen. Zeiträume desselben Artikels dürfen sich nicht überschneiden.',
