    tips: ['Preiserhöhung: beim alten Preis „gültig bis“ setzen (z. B. 30.6.) und einen neuen ab dem Tag danach anlegen.', 'Überschneidungen, negative Preise oder Text statt Zahl meldet die App gleich und speichert nicht.', 'Für alle Artikel nutzbar, nicht nur für Matten. Die Preise ermittelt die App an einer Stelle (Kundenpreis, sonst Artikel).'],
