    answer: 'Der Lauf macht aus den Lieferscheinen des Mattenwechsels Rechnungsentwürfe: je Kunde nach seiner Einstellung – je gewechselter Matte (einzeln oder gesammelt, Preise aus den Lieferscheinen) oder Pauschale je Monat. Vorher zeigt er je Kunde Lieferscheine, Summe und Hinweise. Erstellt werden nur Entwürfe, nie festgeschrieben oder gesendet.',
