    tips: ['Ein Lieferschein und ein Pauschal-Monat kommen nie in zwei Rechnungen – auch nicht einmal je Stück und einmal pauschal. Ein zweiter Lauf erzeugt nichts; Entwurf löschen oder Storno gibt sie frei.', 'Gesperrt mit Hinweis: Preis fehlt im Lieferschein, Kunde nicht in der Fakturierung, Pauschale ohne Betrag.', 'Mit „am Monatsersten vorschlagen“ meldet sich der Lauf in „Zu erledigen“ und beim digitalen Mitarbeiter Buchhaltung (nur „Öffnen“).', 'Die Buchhaltung braucht dafür keinen Zugriff auf den Mattenwechsel: alles steht in den Lieferscheinen.'],
    action: { action: 'mwr-open', label: 'Mattenwechsel abrechnen' },
    related: ['mw-rechnung-freigeben', 'mattenwechsel-kunde', 'mw-lieferscheine', 'festschreiben-und-senden'],
