    tips: ['Rechnungen an Kunden mit Mandat tragen den Hinweis auf den Einzug; versendet zählt das als Vorabankündigung.', 'Dateiformat pain.008.001.08 (aktueller Standard); .02 nur für ältere Bank-Software.'],
